import{_ as o,o as i,c as t,a0 as s}from"./chunks/framework.DhH8_2wW.js";const u=JSON.parse('{"title":"Choose the common options","description":"","frontmatter":{},"headers":[],"relativePath":"markdown-publish--common-configuration.md","filePath":"markdown-publish--common-configuration.md"}'),n={name:"markdown-publish--common-configuration.md"};function a(d,e,r,c,l,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="common-configuration" tabindex="-1">Choose the common options <a class="header-anchor" href="#common-configuration" aria-label="Permalink to &quot;Choose the common options {#common-configuration}&quot;">​</a></h1><p>Engine settings are string values in the <code>publish</code> hash in the Makefile.PL META_MERGE x_documentaton section. They are not nested beneath the selected engine name. These options are shared by the normal workflows:</p><ul><li><p><strong><code>module</code></strong></p><p>Selects <code>mkdocs</code>, <code>vitepress</code>, <code>docusaurus</code>, <code>starlight</code>, or a fully qualified installed subclass. MkDocs is the default. You can also supply your own custom module if inheriting, e.g. &quot;ACME::Publish&quot;</p></li><li><p><strong><code>sources</code></strong></p><p>An array of source directories. Omit it to use the <code>doc/</code> convention and sidecar fallback.</p></li><li><p><strong><code>name</code></strong></p><p>The generated site title. Under MakeMaker it defaults to <code>NAME</code>; standalone use otherwise defaults to <code>Documentation</code>.</p></li><li><p><strong><code>output</code></strong></p><p>The rendered site directory. The default is <code>site/</code>.</p></li><li><p><strong><code>base</code></strong></p><p>The deployment path for generated VitePress, Docusaurus, and Starlight configuration. It begins and ends with a slash, for example <code>/example-client/</code>.</p></li><li><p><strong><code>branch</code></strong></p><p>The local Git publication branch. The default is <code>gh-pages</code>.</p></li><li><p><strong><code>config</code></strong></p><p>An authored native engine configuration. It is authoritative where the selected backend documents that behaviour.</p></li><li><p><strong><code>config_extend</code></strong></p><p>A supplemental file that customises generated defaults. It cannot be combined with <code>config</code>.</p></li><li><p><strong><code>host</code> and <code>port</code></strong></p><p>Override the development server listener where the backend supports it.</p></li></ul><p><code>MARKDOWN_PUBLISH_MODULE</code> environment variables override the configured engine options at runtime. This is handy for comparing renderers without editing <code>Makefile.PL</code> or a project file:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MARKDOWN_PUBLISH_MODULE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">starlight</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publish_serve</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MARKDOWN_PUBLISH_MODULE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vitepress</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publish_build</span></span></code></pre></div><p><code>MARKDOWN_PUBLISH_HOST</code> and <code>MARKDOWN_PUBLISH_PORT</code> provide global preview defaults for port and listening IP. <code>MARKDOWN_PUBLISH_NPM_VERBOSE=1</code> shows normal npm installation output for the Node-based publishers.</p>`,6)])])}const g=o(n,[["render",a]]);export{u as __pageData,g as default};
